// src/V5Atrium.ts
var stasisClip = timeline_default.clips.find((c) => c.id === "h073");
if (!stasisClip) throw Error("The atrial stasis narration cue is missing");
var STASIS_START = stasisClip.start / timeline_default.fps;
var STASIS_DURATION = stasisClip.duration / timeline_default.fps;
var Y = V(0, 1, 0);
var cycle = (x) => (x % 1 + 1) % 1;
var clotSurface = (n, r) => {
  const lobes = 1 + 0.1 * Math.sin(n.x * 9 + n.y * 4) * Math.cos(n.z * 8 - n.x * 3) + 0.045 * Math.sin(n.y * 17 + n.z * 5);
  return V(n.x * 1.13, n.y * 0.72, n.z * 0.86).multiplyScalar(r * lobes);
};
var integratedSmooth = (u) => u <= 0 ? 0 : u >= 1 ? u - 0.5 : u ** 6 - 3 * u ** 5 + 2.5 * u ** 4;
var flowPhase = (time) => {
  const elapsed = time - STASIS_START, span = STASIS_DURATION * 0.52;
  return 0.085 * elapsed - (0.085 - 0.012) * span * integratedSmooth((elapsed - STASIS_DURATION * 0.1) / span);
};
var V5Atrium = class {
  root = new T2.Group();
  center = V();
  arrows = [];
  curve;
  clot = new T2.Group();
  fibrin = [];
  reactionSignals = [];
  weight = 0;
  treatment = 0;
  formation = 0;
  clotRadius = 4e-3;
  constructor(heart) {
    const cavity = heart.getObjectByName("FJ2425_Cavity_of_left_atrium");
    if (!cavity) throw Error("Reference left atrial cavity is missing");
    const bounds = new T2.Box3().setFromObject(cavity), size = bounds.getSize(V());
    bounds.getCenter(this.center);
    const points = Array.from({ length: 40 }, (_, i) => {
      const a = i / 40 * 2 * Math.PI;
      return this.center.clone().add(V(size.x * 0.23 * Math.cos(a), size.y * 0.2 * Math.sin(a), size.z * 0.11 * Math.sin(a * 2)));
    });
    this.curve = new T2.CatmullRomCurve3(points, true);
    heart.getObjectByName("FJ2438_Wall_of_left_atrium")?.traverse((o) => {
      if (o instanceof T2.Mesh) {
        const shell = new T2.Mesh(o.geometry, mat("#b37268", 0.085, 0.65));
        shell.name = "atrial-wall-context";
        shell.matrix.copy(o.matrixWorld);
        shell.matrixAutoUpdate = false;
        this.root.add(shell);
      }
    });
    const guide = new T2.Mesh(new T2.TubeGeometry(this.curve, 120, 1e-4, 8, true), mat("#327e80", 0.15, 0.6));
    guide.name = "qualitative-atrial-flow-path";
    guide.userData.annotation = true;
    this.root.add(guide);
    for (let i = 0; i < 12; i++) {
      const arrow = new T2.Mesh(new T2.ConeGeometry(63e-5, 195e-5, 16), mat("#246f76", 0.94, 0.45));
      arrow.name = "qualitative-atrial-flow-direction";
      arrow.userData.annotation = true;
      this.root.add(arrow);
      this.arrows.push(arrow);
    }
    this.clot.position.copy(this.center).add(V(size.x * 0.14, -size.y * 0.16, 0));
    this.clotRadius = Math.min(46e-4, Math.max(34e-4, Math.min(size.x, size.y, size.z) * 0.18));
    const coreGeometry = new T2.SphereGeometry(this.clotRadius, 48, 32);
    const positions = coreGeometry.attributes.position;
    for (let i = 0; i < positions.count; i++) {
      const n = V().fromBufferAttribute(positions, i).normalize(), p = clotSurface(n, this.clotRadius);
      positions.setXYZ(i, p.x, p.y, p.z);
    }
    coreGeometry.computeVertexNormals();
    const core = new T2.Mesh(coreGeometry, mat("#853f3b", 0.98, 0.66));
    core.name = "single-atrial-thrombus-illustration";
    this.clot.add(core);
    for (let i = 0; i < 22; i++) {
      const a = i * 2.39996, z = -0.87 + 1.74 * (i + 0.5) / 22;
      const axis = V(Math.sqrt(1 - z * z) * Math.cos(a), z, Math.sqrt(1 - z * z) * Math.sin(a));
      const tangent = V(Math.sin(a + 0.7), 0.43, Math.cos(a + 0.7)).cross(axis).normalize();
      const threadPoints = Array.from({ length: 30 }, (_, j) => {
        const u = j / 29, angle = -1.05 + u * (1.6 + 0.35 * Math.sin(i));
        const n = axis.clone().multiplyScalar(Math.cos(angle)).addScaledVector(tangent, Math.sin(angle)).normalize();
        return clotSurface(n, this.clotRadius * 1.026);
      });
      const thread = new T2.Mesh(new T2.TubeGeometry(new T2.CatmullRomCurve3(threadPoints), 44, 44e-6, 7, false), mat("#d8bca4", 0.58, 0.8));
      thread.name = "established-fibrin-schematic";
      thread.userData.annotation = true;
      this.clot.add(thread);
      this.fibrin.push(thread);
    }
    this.root.add(this.clot);
    for (let i = 0; i < 16; i++) {
      const pulse = new T2.Mesh(new T2.SphereGeometry(4e-4, 14, 10), mat("#b58b42", 0.86, 0.45));
      pulse.name = "new-coagulation-reaction-marker";
      pulse.userData.annotation = true;
      this.root.add(pulse);
      this.reactionSignals.push(pulse);
    }
    this.root.userData = { source: "BodyParts3D FJ2425 cavity / FJ2438 wall", units: "metres", cavityBounds: [bounds.min.toArray(), bounds.max.toArray()], representation: "Qualitative directional flow and reaction markers; one illustrative atrial clot, not a patient scan or CFD", flowPhase: "Analytic integral of decreasing quintic-smoothed speed; independent of update history", treatment: "Reduces new coagulation activity; existing clot and established fibrin remain" };
  }
  getAnchors() {
    return { leftAtrium: this.center.clone(), atrialClot: this.clot.position.clone() };
  }
  update(time, weight, progress, markerWeight = weight, treatment = 0) {
    this.weight = weight;
    this.treatment = treatment;
    visibility(this.root, weight);
    this.root.visible = Math.max(weight, markerWeight) > 1e-4;
    const phase = flowPhase(time);
    this.arrows.forEach((arrow, i) => {
      const q = cycle(phase + i / this.arrows.length);
      arrow.position.copy(this.curve.getPointAt(q));
      arrow.quaternion.setFromUnitVectors(Y, this.curve.getTangentAt(q).normalize());
      visibility(arrow, markerWeight);
    });
    const formation = smooth((progress - 0.24) / 0.56);
    this.formation = formation;
    this.clot.scale.setScalar(0.36 + 0.64 * formation);
    visibility(this.clot, markerWeight * formation);
    this.fibrin.forEach((thread, i) => visibility(thread, markerWeight * formation * smooth((progress - 0.38 - i * 0.012) / 0.24)));
    const inhibition = smooth((treatment - 0.1) / 0.7);
    this.reactionSignals.forEach((signal, i) => {
      const q = cycle((time - STASIS_START) * 0.22 + i / this.reactionSignals.length), a = i * 2.39996;
      const radial = V(Math.cos(a) * 1.13, Math.sin(a * 0.71) * 0.72, Math.sin(a) * 0.86).normalize();
      const distance = this.clotRadius * (2.25 - 1.12 * q);
      signal.position.copy(this.clot.position).add(radial.multiplyScalar(distance));
      const arrival = smooth(q / 0.14) * (1 - smooth((q - 0.76) / 0.24));
      const remaining = i < 3 ? 1 - 0.55 * inhibition : 1 - 0.98 * inhibition;
      visibility(signal, markerWeight * formation * arrival * remaining);
    });
  }
  labels() {
    return this.weight > 0.3 ? [
      { text: "\u5DE6\u5FC3\u623F", point: this.center.clone(), side: "right", weight: this.weight },
      { text: this.treatment > 0.1 ? "\u65B0\u589E\u51DD\u8840\u53CD\u5E94\u51CF\u5C11 \xB7 \u793A\u610F" : "\u5C40\u90E8\u8840\u6D41\u53D8\u7F13 \xB7 \u793A\u610F", point: this.center.clone().add(V(0, 4e-3, 0)), side: "left", weight: this.weight },
      { text: "\u5FC3\u623F\u5185\u8840\u6813 \xB7 \u793A\u610F", point: this.clot.position.clone(), side: "right", weight: this.weight * this.formation }
    ] : [];
  }
};
export {
  V5Atrium
};
